\pset footer off
-- ALL TABLE ROW COUNTS
SELECT table_name || '|' || (xpath('/row/cnt/text()', query_to_xml(format('SELECT count(*) AS cnt FROM public.%I', table_name), false, true, '')))[1]::text
FROM information_schema.tables WHERE table_schema='public' AND table_type='BASE TABLE' ORDER BY table_name;
-- CONTENT HASHES (old columns only)
SELECT 'H|ApprovalActionLog|' || count(*) || '|' || coalesce(md5(string_agg(row_to_json(x)::text, '' ORDER BY x."id")),'EMPTY') FROM (SELECT "id","approvalInstanceId","action","actorUserId","comment","createdAt","metadata","approvedRoleKey","signatureFileIdSnapshot","signatureSha256Snapshot","representedUserId","signatureVersionIdSnapshot" FROM public."ApprovalActionLog") x;
SELECT 'H|ApprovalInstance|' || count(*) || '|' || coalesce(md5(string_agg(row_to_json(x)::text, '' ORDER BY x."id")),'EMPTY') FROM (SELECT "id","flowType","businessType","businessId","status","currentNodeIndex","frozenNodes","applicantUserId","createdAt","updatedAt" FROM public."ApprovalInstance") x;
SELECT 'H|AuditLog|' || count(*) || '|' || coalesce(md5(string_agg(row_to_json(x)::text, '' ORDER BY x."id")),'EMPTY') FROM (SELECT "id","actorUserId","action","businessType","businessId","ipAddress","userAgent","metadata","createdAt" FROM public."AuditLog") x;
SELECT 'H|CompanyEntity|' || count(*) || '|' || coalesce(md5(string_agg(row_to_json(x)::text, '' ORDER BY x."id")),'EMPTY') FROM (SELECT "id","name","unifiedSocialCreditCode","isActive","createdAt","updatedAt","registeredAddress","dataStatus","currentVersionNo" FROM public."CompanyEntity") x;
SELECT 'H|CompanyEntityVersion|' || count(*) || '|' || coalesce(md5(string_agg(row_to_json(x)::text, '' ORDER BY x."id")),'EMPTY') FROM (SELECT "id","companyEntityId","versionNo","name","unifiedSocialCreditCode","registeredAddress","isActive","action","actorUserId","actorRoleKey","createdAt" FROM public."CompanyEntityVersion") x;
SELECT 'H|Contract|' || count(*) || '|' || coalesce(md5(string_agg(row_to_json(x)::text, '' ORDER BY x."id")),'EMPTY') FROM (SELECT "id","projectId","code","name","counterparty","createdAt","updatedAt","companyEntityId","companyEntityName","contractTypeKey","ownerUserId","temporaryCode","voidedAt","voidedReason","source","businessScenarioId","scenarioTemplateMappingId","scenarioSnapshot","settlementClosedAt","finalSettlementId" FROM public."Contract") x;
SELECT 'H|ContractPartySnapshot|' || count(*) || '|' || coalesce(md5(string_agg(row_to_json(x)::text, '' ORDER BY x."id")),'EMPTY') FROM (SELECT "id","contractVersionId","roleKey","displayOrder","businessPartyVersionId","snapshot","createdAt" FROM public."ContractPartySnapshot") x;
SELECT 'H|ContractVersion|' || count(*) || '|' || coalesce(md5(string_agg(row_to_json(x)::text, '' ORDER BY x."id")),'EMPTY') FROM (SELECT "id","contractId","versionNo","changeType","status","amountCents","effectiveAt","createdAt","updatedAt","amountAdjustmentReason","amountSource","businessTemplateVersionId","clauseSnapshot","draftData","draftRevision","layoutTemplateVersionId","pricingNature","readinessSnapshot","templateSnapshot","baseVersionId","supersedesVersionId","changeReason","changeDirection","changeAmountCents","originalBaseAmountCents","cumulativeIncreaseCents","cumulativeDecreaseCents","amountLimitType","invoiceType","taxMode","defaultTaxRatePercent","taxFactStatus","taxFactSource","taxFactExplanation","taxFactEvidenceFileId","taxFactRevision","taxFactsFrozenAt","companyEntityIdSnapshot","companyEntityVersionId","companyEntityNameSnapshot","companyEntityCreditCodeSnapshot","companyEntityRegisteredAddressSnapshot","contractGovernanceVersion","abandonedAt","abandonedByUserId","abandonReason","copiedFromContractVersionId","settlementMode","settlementModeSource","settlementModeConfirmedByUserId","settlementModeConfirmedAt","firstSubmittedAt","latestDraftPreviewDocumentId","estimatedAmountCents","signingSubjectType","affiliateAssignmentId","affiliateBusinessPartyVersionId","affiliateNameSnapshot","affiliateCreditCodeSnapshot","endedAt","documentContentRevision","documentContentFingerprint","numericProtocolVersion","amountYuan","originalSignedNumber" FROM public."ContractVersion") x;
SELECT 'H|FileObject|' || count(*) || '|' || coalesce(md5(string_agg(row_to_json(x)::text, '' ORDER BY x."id")),'EMPTY') FROM (SELECT "id","bucket","objectKey","originalName","mimeType","sizeBytes","uploadedByUserId","createdAt","contentSha256","storageStatus","supersedesFileObjectId","purgeReceiptId" FROM public."FileObject") x;
SELECT 'H|OperatingTakeoverBatch|' || count(*) || '|' || coalesce(md5(string_agg(row_to_json(x)::text, '' ORDER BY x."id")),'EMPTY') FROM (SELECT "id","projectId","batchNo","sourceFileId","sourceFileName","sceneKeys","status","revision","importFingerprint","totalRows","readyRows","blockedRows","warningRows","createdByUserId","activatedAt","activatedByUserId","createdAt","updatedAt" FROM public."OperatingTakeoverBatch") x;
SELECT 'H|OperatingTakeoverRow|' || count(*) || '|' || coalesce(md5(string_agg(row_to_json(x)::text, '' ORDER BY x."id")),'EMPTY') FROM (SELECT "id","batchId","rowNo","sceneKey","definitionVersion","businessRef","occurredAt","periodLabel","amountCents","valuesSnapshot","evidenceLevel","reviewStatus","duplicateStatus","duplicateNote","reviewConclusion","revision","generatedFactId","createdAt","updatedAt" FROM public."OperatingTakeoverRow") x;
SELECT 'H|PaymentExecution|' || count(*) || '|' || coalesce(md5(string_agg(row_to_json(x)::text, '' ORDER BY x."id")),'EMPTY') FROM (SELECT "id","paymentRequestId","settlementId","amountCents","paidAt","executedByUserId","voucherFileId","createdAt","paymentSubjectType","idempotencyKey","companyEntityIdSnapshot","companyEntityNameSnapshot","companyEntityCreditCodeSnapshot","payerAttestationFingerprint" FROM public."PaymentExecution") x;
SELECT 'H|PaymentRequest|' || count(*) || '|' || coalesce(md5(string_agg(row_to_json(x)::text, '' ORDER BY x."id")),'EMPTY') FROM (SELECT "id","projectId","settlementId","contractId","contractVersionId","paymentTermsVersionId","code","status","requestedAmountCents","approvedAmountCents","paidAmountCents","dueDate","createdAt","updatedAt","sourceType","paymentTermsStageId","abandonedAt","abandonedByUserId","abandonReason","paymentMatter","amountCalculationExplanation","paymentSubjectType" FROM public."PaymentRequest") x;
SELECT 'H|PaymentTermsStage|' || count(*) || '|' || coalesce(md5(string_agg(row_to_json(x)::text, '' ORDER BY x."id")),'EMPTY') FROM (SELECT "id","paymentTermsVersionId","name","basis","ratioBps","fixedAmountCents","triggerEvent","dueDays","requiresInvoice","allowsEarlyPayment","allowsInstallments","retentionBps","originalText","createdAt","stageType","triggerAnchor","advanceDeductionMode","advanceDeductionRatioBps","advanceDeductionStartRatioBps" FROM public."PaymentTermsStage") x;
SELECT 'H|PaymentTermsVersion|' || count(*) || '|' || coalesce(md5(string_agg(row_to_json(x)::text, '' ORDER BY x."id")),'EMPTY') FROM (SELECT "id","contractId","contractVersionId","versionNo","status","originalText","createdAt","updatedAt" FROM public."PaymentTermsVersion") x;
SELECT 'H|Project|' || count(*) || '|' || coalesce(md5(string_agg(row_to_json(x)::text, '' ORDER BY x."id")),'EMPTY') FROM (SELECT "id","code","name","isActive","createdAt","updatedAt","operatingLedgerEffectiveDate","takeoverCompletedDate","takeoverStatus","constructionEnterpriseLockedAt" FROM public."Project") x;
SELECT 'H|ProjectParticipatingCompany|' || count(*) || '|' || coalesce(md5(string_agg(row_to_json(x)::text, '' ORDER BY x."id")),'EMPTY') FROM (SELECT "id","projectId","companyEntityId","companyEntityVersionId","companyNameSnapshot","companyCreditCodeSnapshot","effectiveFrom","endedAt","changeReason","addedByUserId","endedByUserId","createdAt","updatedAt" FROM public."ProjectParticipatingCompany") x;
SELECT 'H|Settlement|' || count(*) || '|' || coalesce(md5(string_agg(row_to_json(x)::text, '' ORDER BY x."id")),'EMPTY') FROM (SELECT "id","projectId","contractId","contractVersionId","paymentTermsVersionId","code","periodLabel","status","amountCents","payableAmountCents","paidAmountCents","createdAt","updatedAt","isFinal","finalCumulativeAmountCents","sourceType","sourceTakeoverId","settlementTemplateVersionId","invoiceTypeSnapshot","taxFactRevisionSnapshot","governanceVersion","fieldReviewerUserId","fieldReviewerRoleKey","preparedByUserId","preparerSignatureFileId","preparerSignatureSha256","finalScopeCompleted","finalPriorSettlementsIncluded","finalNoOutstandingSettlements","finalWithinContractCap","finalNoFurtherOrdinarySettlements","preparerSignatureVersionId","processId","periodStart","periodEnd","finalDeclarationVersion","finalDeclarationSnapshot","calculationVersion","sourceSnapshotToken" FROM public."Settlement") x;
SELECT 'H|SettlementLine|' || count(*) || '|' || coalesce(md5(string_agg(row_to_json(x)::text, '' ORDER BY x."id")),'EMPTY') FROM (SELECT "id","settlementId","contractBillRowId","sourceType","name","unit","quantity","unitPriceCents","amountCents","reason","remark","sortOrder","createdAt","updatedAt","calculationMode","contractQuantitySnapshot","unitPriceSnapshot","taxRatePercentSnapshot","pricingModeSnapshot","taxExclusiveAmountCents","taxAmountCents","lineKey","contractBillRowLineageId","sourceContractVersionId","sourceItemType","occurredOn","description","pricingBasis","relatedSettlementLineId","overageReason","adjustmentKind" FROM public."SettlementLine") x;
SELECT 'H|SpotProcurement|' || count(*) || '|' || coalesce(md5(string_agg(row_to_json(x)::text, '' ORDER BY x."id")),'EMPTY') FROM (SELECT "id","projectId","code","supplierPartyId","supplierKey","supplierNameSnapshot","applicantUserId","handlerUserId","currentVersionId","status","approvedAmountCents","actualCostCents","closedAt","voidedAt","voidedByUserId","voidReason","createdAt","updatedAt","abandonedAt","abandonedByUserId","abandonReason" FROM public."SpotProcurement") x;
SELECT 'H|SpotProcurementLine|' || count(*) || '|' || coalesce(md5(string_agg(row_to_json(x)::text, '' ORDER BY x."id")),'EMPTY') FROM (SELECT "id","versionId","sortOrder","materialName","specification","unit","quantity","invoiceMode","invoiceType","vatRateOptionId","vatRateValueSnapshot","vatRateLabelSnapshot","unitPrice","amountCents","usageLocation","note","createdAt","estimatedUnitPrice","estimatedAmount" FROM public."SpotProcurementLine") x;
-- MONEY SUMS
SELECT 'M|ContractVersion|amountCents|'||coalesce(sum("amountCents"),0)||'|changeAmount|'||coalesce(sum("changeAmountCents"),0)||'|count|'||count(*) FROM "ContractVersion";
SELECT 'M|Settlement|amount|'||coalesce(sum("amountCents"),0)||'|payable|'||coalesce(sum("payableAmountCents"),0)||'|paid|'||coalesce(sum("paidAmountCents"),0)||'|count|'||count(*) FROM "Settlement";
SELECT 'M|SettlementLine|amount|'||coalesce(sum("amountCents"),0)||'|count|'||count(*) FROM "SettlementLine";
SELECT 'M|PaymentRequest|requested|'||coalesce(sum("requestedAmountCents"),0)||'|approved|'||coalesce(sum("approvedAmountCents"),0)||'|paid|'||coalesce(sum("paidAmountCents"),0)||'|count|'||count(*) FROM "PaymentRequest";
SELECT 'M|PaymentExecution|amount|'||coalesce(sum("amountCents"),0)||'|count|'||count(*) FROM "PaymentExecution";
SELECT 'M|OperatingTakeoverRow|amount|'||coalesce(sum("amountCents"),0)||'|count|'||count(*) FROM "OperatingTakeoverRow";
SELECT 'M|AuditLog|count|'||count(*) FROM "AuditLog";
SELECT 'M|Company|'||co."name"||'|contractAmount|'||coalesce(sum(v."amountCents"),0)||'|versions|'||count(v.id) FROM "CompanyEntity" co LEFT JOIN "Contract" c ON c."companyEntityId"=co.id LEFT JOIN "ContractVersion" v ON v."contractId"=c.id GROUP BY co.id,co."name" ORDER BY 1;
SELECT 'M|Project|'||p.code||'|settlementPayable|'||coalesce(sum(s."payableAmountCents"),0)||'|paid|'||coalesce(sum(s."paidAmountCents"),0) FROM "Project" p LEFT JOIN "Settlement" s ON s."projectId"=p.id GROUP BY p.id,p.code ORDER BY 1;
-- INTEGRITY
SELECT 'I|orphan_settlement_version|'||count(*) FROM "Settlement" s LEFT JOIN "ContractVersion" v ON v.id=s."contractVersionId" WHERE v.id IS NULL OR v."contractId"<>s."contractId";
SELECT 'I|orphan_request_settlement|'||count(*) FROM "PaymentRequest" r LEFT JOIN "Settlement" s ON s.id=r."settlementId" WHERE s.id IS NULL OR s."contractVersionId"<>r."contractVersionId";
SELECT 'I|orphan_execution_request|'||count(*) FROM "PaymentExecution" e LEFT JOIN "PaymentRequest" r ON r.id=e."paymentRequestId" WHERE r.id IS NULL;
SELECT 'I|request_paid_mismatch|'||count(*) FROM "PaymentRequest" r WHERE r."paidAmountCents"<>(SELECT coalesce(sum(e."amountCents"),0) FROM "PaymentExecution" e WHERE e."paymentRequestId"=r.id);
SELECT 'I|settlement_paid_mismatch|'||count(*) FROM "Settlement" s WHERE s."paidAmountCents"<>(SELECT coalesce(sum(r."paidAmountCents"),0) FROM "PaymentRequest" r WHERE r."settlementId"=s.id);
SELECT 'I|line_sum_mismatch|'||count(*) FROM "Settlement" s WHERE s."amountCents"<>(SELECT coalesce(sum(l."amountCents"),0) FROM "SettlementLine" l WHERE l."settlementId"=s.id);
SELECT 'I|invalid_base_version|' || count(*)
FROM "ContractVersion" v LEFT JOIN "ContractVersion" b ON b.id=v."baseVersionId"
WHERE v."baseVersionId" IS NOT NULL AND (b.id IS NULL OR b."contractId"<>v."contractId");
SELECT 'I|invalid_superseded_version|' || count(*)
FROM "ContractVersion" v LEFT JOIN "ContractVersion" previous ON previous.id=v."supersedesVersionId"
WHERE v."supersedesVersionId" IS NOT NULL AND (previous.id IS NULL OR previous."contractId"<>v."contractId");
SELECT 'I|audit_total|'||count(*)||'|actorDistinct|'||count(distinct "actorUserId") FROM "AuditLog";
SELECT 'I|file_hash_distinct|'||count(distinct "contentSha256")||'|files|'||count(*) FROM "FileObject";
